/* Isolated visual proposal only: move original rendered nodes; never fetch,
 * submit, calculate balances, accept quests, save titles or change gameplay.
 */
(function () {
  'use strict';
  // Preserved original JPEG bytes; private local preview only. No remote URL.
  const profileAvatarData = 'data:image/jpeg;base64,';
  const profileStationData = {
    '1': {name:'Mars',src:'data:image/jpeg;base64,'},
    '2': {name:'Earth',src:'data:image/jpeg;base64,'},
    '3': {name:'Venus',src:'data:image/jpeg;base64,'}
  };
  function element(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }
  function run() {
    const body = document.body;
    if (!body.classList.contains('historical-site') || window.AndromedaVisualPilotProposal) return;
    body.classList.add('visual-proposal-pilot');
    const proof = {version:1, businessRequestsAdded:0, originalNodesRetained:true,
      tagColor:'Neutral inherited pilot-name text; no tag-specific color, badge or background',
      profile:'not present', history:'not present'};
    // Keep the existing frontend's quantity offset, which depends on the
    // number of real quantity presets. Never replace it with a fixed guess.
    document.querySelectorAll('.hist-shop-detail .qty-input').forEach(input => {
      const action = input.closest('.ship-action,.design-action,.item-action');
      if (action) action.style.setProperty('--vp-stepper-top', /^\d+(?:\.\d+)?px$/.test(input.style.top) ? input.style.top : '88px');
    });
    const sheet = document.querySelector('.rev6-profile-sheet');
    if (sheet && !sheet.querySelector('.vp-profile-columns')) {
      const rows = Array.from(sheet.querySelectorAll('.stats-list > .stat-row'));
      const identity = sheet.querySelector('.rev6-profile-identity');
      const facts = sheet.querySelector('.rev7-profile-facts');
      const tools = sheet.querySelector('.rev6-profile-links');
      const originalLists = Array.from(sheet.querySelectorAll('.stats-list'));
      const columns = element('div', 'vp-profile-columns');
      const overview = element('section', 'vp-profile-overview');
      const main = element('section', 'vp-profile-main');
      const avatar = element('img', 'vp-profile-avatar');
      avatar.src = profileAvatarData; avatar.alt = 'Default profile image';
      avatar.width = 110; avatar.height = 120; avatar.draggable = false;
      overview.appendChild(avatar);
      if (identity) {
        const title = identity.querySelector('.card-title');
        if (title) title.textContent = 'Name';
        const header = identity.querySelector('.card-header');
        const nameRow = identity.querySelector('.pilot-name-row,.pilot-name');
        const rankRow = identity.querySelector('.pilot-rank-row');
        const oldPilotHeader = identity.querySelector('.pilot-header');
        const companyIcon = identity.querySelector('img.company-icon, img.company-mini-icon, img[alt="Company"]');
        if (header) {
          const localId = Array.from(header.children).find(node => node !== title && /^\s*ID\s*:/i.test(node.textContent));
          if (localId) { localId.hidden = true; localId.classList.add('vp-local-pilot-id'); }
          if (nameRow) {
            if (companyIcon && !nameRow.contains(companyIcon)) nameRow.appendChild(companyIcon);
            header.appendChild(nameRow);
          }
          if (rankRow) header.appendChild(rankRow);
        }
        if (oldPilotHeader && !oldPilotHeader.textContent.trim() && !oldPilotHeader.querySelector('img,a,button,input,select,textarea')) {
          oldPilotHeader.hidden = true; oldPilotHeader.classList.add('vp-empty-pilot-header');
        }
        overview.appendChild(identity);
      }
      if (facts) overview.appendChild(facts);
      if (tools) overview.appendChild(tools);
      const player = element('section', 'vp-profile-player');
      player.appendChild(element('h2', '', 'Player stats'));
      const playerList = element('div', 'stats-list');
      const resources = element('section', 'vp-profile-resources');
      resources.appendChild(element('h2', '', 'Account resources'));
      const resourceList = element('div', 'stats-list');
      rows.forEach(row => {
        const label = row.querySelector('.stat-label')?.textContent.trim().toLowerCase();
        (['experience', 'honor', 'rank points'].includes(label) ? playerList : resourceList).appendChild(row);
      });
      if (playerList.children.length) { player.appendChild(playerList); main.appendChild(player); }
      if (resourceList.children.length) { resources.appendChild(resourceList); main.appendChild(resources); }
      const station = element('aside', 'vp-profile-station');
      station.setAttribute('aria-hidden', 'true');
      const factionIcon = identity?.querySelector('img.company-icon, img.company-mini-icon, img[alt="Company"]');
      const factionMatch = (factionIcon?.getAttribute('src') || '').match(/(?:^|\/)img\/ranks\/company\/([123])\.png(?:[?#]|$)/);
      const stationChoice = factionMatch ? profileStationData[factionMatch[1]] : null;
      station.hidden = !stationChoice;
      if (stationChoice) {
        station.dataset.faction = factionMatch[1];
        station.dataset.station = stationChoice.name.toLowerCase();
        const stationImage = element('img', 'vp-profile-station-image');
        stationImage.src = stationChoice.src; stationImage.alt = '';
        stationImage.width = 238; stationImage.height = 393; stationImage.draggable = false;
        station.appendChild(stationImage);
      }
      columns.append(overview, main, station);
      originalLists.forEach(list => { list.hidden = true; });
      sheet.appendChild(columns);
      proof.profile = {allOriginalStatRowsConnected:rows.every(row => row.isConnected),
        originalStatRowCount:rows.length, sameOriginalIdentity:identity?.isConnected === true,
        sameOriginalCompanyLink:!tools || tools.isConnected, unsupportedPersonalFieldsAdded:false,
        originalStatsValuesRecomputed:false, duplicateWalletIdentifiersAdded:false,
        defaultAvatar:{source:'PrivateKrypton preserved default silhouette; not a user-uploaded account avatar',width:110,height:120},
        historicalStation:{source:'DoPs template/UU original station art; three-faction selection is an Andromeda adaptation',name:stationChoice?.name || null,faction:factionMatch ? Number(factionMatch[1]) : null,width:238,height:393,decorativeOnly:true},
        identityOrder:'Name; same tag+username+company icon; same rank icon+label. Local ID node hidden, original global HUD ID retained.',
        originalFactionIconRetained:!identity || identity.querySelector('img.company-icon, img.company-mini-icon, img[alt="Company"]')?.isConnected === true};
    }
    const history = document.querySelector('.hist-entire-history');
    if (history && !history.closest('.vp-history-layout')) {
      const rows = Array.from(history.querySelectorAll('[data-log-id]'));
      const links = Array.from(history.querySelectorAll('a'));
      const layout = element('div', 'vp-history-layout');
      const rail = element('aside', 'vp-history-rail');
      rail.setAttribute('aria-hidden', 'true');
      history.before(layout);
      layout.append(rail, history);
      proof.history = {allOriginalRowsConnected:rows.every(row => row.isConnected),
        samePaginationAnchors:links.every(link => link.isConnected),
        originalDateActionTable:true, frame:'PrivateKrypton complementary bg_auktion.png; original DoPs JPG missing'};
    }
    window.AndromedaVisualPilotProposal = proof;
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run, {once:true});
  else run();
})();
